import re
from typing import Optional

from fastapi import APIRouter, Header, HTTPException

from db.database import (delete_analysis, get_analysis, get_cached, list_history,
                         make_cache_key, save_analysis)
from llm.client import LLMError
from orchestrator.orchestrator import PipelineError, run_pipeline
from schemas.request_schema import AnalyzeRequest
from schemas.response_schema import AnalyzeResponse

router = APIRouter()

# Anonymous per-browser id generated by the frontend; it scopes history to that browser
CLIENT_ID_PATTERN = re.compile(r"^[A-Za-z0-9-]{8,64}$")


def _client_id(value: Optional[str]) -> Optional[str]:
    return value if value and CLIENT_ID_PATTERN.match(value) else None


def _require_client_id(value: Optional[str]) -> str:
    client_id = _client_id(value)
    if not client_id:
        raise HTTPException(status_code=400, detail="Missing or invalid X-Client-Id header.")
    return client_id


@router.post("/analyze", response_model=AnalyzeResponse)
def analyze(request: AnalyzeRequest, x_client_id: Optional[str] = Header(None)):
    """
    Entry API for code/problem analysis
    """
    cache_key = make_cache_key(request)
    result = get_cached(cache_key)
    cached = result is not None

    if not cached:
        try:
            result = run_pipeline(request)
        except PipelineError as e:
            raise HTTPException(status_code=400, detail=str(e))
        except LLMError as e:
            raise HTTPException(status_code=e.status_code, detail=str(e))

    analysis_id = None
    client_id = _client_id(x_client_id)
    if client_id:
        input_text = (request.input or "").strip() or "\n\n".join(
            p.strip() for p in (request.problem, request.code) if p and p.strip())
        analysis_id = save_analysis(client_id, cache_key, input_text, result)

    return {**result, "id": analysis_id, "cached": cached}


@router.get("/history")
def history(x_client_id: Optional[str] = Header(None)):
    return list_history(_require_client_id(x_client_id))


@router.get("/history/{analysis_id}")
def history_item(analysis_id: int, x_client_id: Optional[str] = Header(None)):
    item = get_analysis(_require_client_id(x_client_id), analysis_id)
    if not item:
        raise HTTPException(status_code=404, detail="Analysis not found.")
    return item


@router.delete("/history/{analysis_id}")
def history_delete(analysis_id: int, x_client_id: Optional[str] = Header(None)):
    if not delete_analysis(_require_client_id(x_client_id), analysis_id):
        raise HTTPException(status_code=404, detail="Analysis not found.")
    return {"deleted": analysis_id}
